class Solution {
    public int minCut(String s) {
        int n = s.length();
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) dp[i] = i;
        for (int mid = 0; mid < n; mid++) {
            for (int d = 0; mid - d >= 0 && mid + d < n && s.charAt(mid - d) == s.charAt(mid + d); d++) {
                dp[mid + d] = mid - d == 0 ? 0 : Math.min(dp[mid + d], dp[mid - d - 1] + 1);
            }
            for (int d = 0; mid - d >= 0 && mid + d + 1 < n && s.charAt(mid - d) == s.charAt(mid + d + 1); d++) {
                dp[mid + d + 1] = mid - d == 0 ? 0 : Math.min(dp[mid + d + 1], dp[mid - d - 1] + 1);
            }
        }
        return dp[n - 1];
    }
}
